div.script:
$(document).ready(function(){
console.log('get function');
$('.o_trial_reports_caret_icon.down').click(function(ev) {
console.log('sachin',$(this))

if($(this).hasClass('cluster')){
    var elementId = $(this).attr('id');
    console.log($('.o_trial_reports_caret_icon.right.p'+ elementId));
    $('.cluster_child' + elementId.replace('cluster_debit','')).addClass('d-none');
    $('.o_trial_reports_caret_icon.down.'+ elementId).click()
    $('#'+ elementId +'.cluster.o_trial_reports_caret_icon.right').removeClass('d-none');
    $('#'+ elementId +'.cluster.o_trial_reports_caret_icon.down').addClass('d-none');
}
else{

    console.log(ev,'Closed in else');
    console.log('this', this);
    var elementId = $(this).attr('id');
    console.log('Element ID:', elementId);

    // Hide all elements with the ID as their class
    $('.c' + elementId).addClass('d-none');
    $('.o_trial_reports_caret_icon.right.p' + elementId).removeClass('d-none');
    $('.o_trial_reports_caret_icon.down.p' + elementId).addClass('d-none');
}

});

$('.o_trial_reports_caret_icon.right').click(function(ev) {
//console.log('sachin right',$(this));
if($(this).hasClass('cluster')){
    var elementId = $(this).attr('id');
    console.log("id",elementId);
    //$('.o_trial_reports_caret_icon.down.p'+ elementId.replace('cluster','')).click()
    //console.log('.o_trial_reports_caret_icon.down.'+ elementId);
    //console.log($('.o_trial_reports_caret_icon.down.'+ elementId));
    $('.cluster_child' + elementId.replace('cluster_debit','')).removeClass('d-none');
    $('#'+ elementId +'.cluster.o_trial_reports_caret_icon.down').removeClass('d-none');
    $('#'+ elementId +'.cluster.o_trial_reports_caret_icon.right').addClass('d-none');
    //$('.o_trial_reports_caret_icon.right.'+ elementId).click()
}
else{
    console.log(ev,'Opened in else');
    console.log('this', this);
    var elementId = $(this).attr('id');
    console.log('Elementads ID:Opened', elementId);

    // Hide all elements with the ID as their class
    $('.c' + elementId).removeClass('d-none');
    $('.o_trial_reports_caret_icon.down.p' + elementId).removeClass('d-none');
    $('.o_trial_reports_caret_icon.right.p' + elementId).addClass('d-none');
}
});
})
